module.exports = "/* Estilos do Painel IPTV - Tema Bege Clarinho & Azul Claro com Suporte Responsivo Geral */\n\n:root {\n  --bg-beige: #f7f3ea;\n  --bg-card: #ffffff;\n  --bg-subtle: #f0e9dd;\n  --border-color: #cbd5e1;\n  --color-primary: #0284c7;   /* Azul Claro */\n  --color-primary-hover: #0369a1;\n  --color-orange: #f97316;    /* Laranja Brilhante */\n  --text-main: #000000;\n  --text-muted: #000000;\n}\n\nbody {\n  background-color: var(--bg-beige);\n  color: #000000 !important;\n  font-size: 16px;\n  line-height: 1.6;\n  padding-bottom: 70px; /* Espaço para menu inferior no celular */\n}\n\n/* Regra Geral de Alta Visibilidade: Texto em Preto Nítido */\np, span:not(.text-white), h1, h2, h3, h4, h5, h6, label, td, th {\n  color: #000000 !important;\n}\n\nlabel, h1, h2, h3, th {\n  font-weight: 700 !important;\n}\n\n@media (min-width: 768px) {\n  body {\n    padding-bottom: 0px;\n  }\n}\n\n/* Tamanho de Fonte Geral Aumentado */\ninput, select, textarea, button {\n  font-size: 15px !important;\n}\n\nh1 { font-size: 24px !important; }\nh2 { font-size: 20px !important; }\nh3 { font-size: 18px !important; }\n\n/* Navegação por Abas */\n.nav-tab {\n  color: #475569;\n  background-color: #efe8dc;\n  border: 1px solid #e2d7c5;\n  font-weight: 600;\n  font-size: 15px !important;\n  white-space: nowrap;\n}\n\n.nav-tab:hover {\n  color: #0284c7;\n  background-color: #e5dccf;\n}\n\n.nav-tab.active {\n  color: #ffffff !important;\n  background-color: #0284c7 !important;\n  border-color: #38bdf8 !important;\n  box-shadow: 0 4px 14px 0 rgba(2, 132, 199, 0.35);\n}\n\n/* Inputs e Formulários Claros */\ninput[type=\"text\"], input[type=\"password\"], input[type=\"date\"], input[type=\"number\"], select, textarea {\n  background-color: #ffffff !important;\n  color: #0f172a !important;\n  border-color: #cbd5e1 !important;\n}\n\ninput[type=\"text\"]:focus, input[type=\"password\"]:focus, select:focus, textarea:focus {\n  border-color: #0284c7 !important;\n  ring: 2px #0284c7 !important;\n}\n\n/* Custom Scrollbar */\n::-webkit-scrollbar {\n  width: 6px;\n  height: 6px;\n}\n\n::-webkit-scrollbar-track {\n  background: #f0e8db;\n}\n\n::-webkit-scrollbar-thumb {\n  background: #cbd5e1;\n  border-radius: 4px;\n}\n\n::-webkit-scrollbar-thumb:hover {\n  background: #0284c7;\n}\n\n/* OTIMIZAÇÕES RESPONSIVAS PARA CELULARES E TABLETS */\n@media (max-width: 640px) {\n  /* Evita auto-zoom do navegador no iPhone ao clicar em inputs */\n  input[type=\"text\"], input[type=\"password\"], input[type=\"date\"], input[type=\"number\"], select, textarea {\n    font-size: 16px !important;\n  }\n  \n  /* Botões e alvos de toque maiores no celular */\n  button, .nav-tab {\n    min-height: 44px;\n  }\n\n  /* Ajustes de cabeçalho no celular */\n  header {\n    padding-left: 0.75rem !important;\n    padding-right: 0.75rem !important;\n    padding-top: 0.75rem !important;\n    padding-bottom: 0.75rem !important;\n  }\n  \n  h1 { font-size: 1.1rem !important; }\n  h2 { font-size: 1rem !important; }\n  h3 { font-size: 0.95rem !important; }\n}\n\n/* Barra de Navegação Inferior para Celulares (Bottom Nav Bar) */\n.mobile-bottom-nav {\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  background: rgba(255, 255, 255, 0.96);\n  backdrop-filter: blur(12px);\n  border-top: 1px solid #e2d7c5;\n  z-index: 45;\n  display: flex;\n  justify-content: space-around;\n  align-items: center;\n  padding: 6px 4px;\n  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.08);\n}\n\n.mobile-bottom-btn {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  color: #64748b;\n  font-size: 11px;\n  font-weight: 700;\n  padding: 6px 10px;\n  border-radius: 12px;\n  transition: all 0.2s ease;\n}\n\n.mobile-bottom-btn.active {\n  color: #0284c7;\n  background-color: #e0f2fe;\n}\n\n.mobile-bottom-btn i {\n  font-size: 18px;\n  margin-bottom: 2px;\n}\n";